<script setup>
import { computed,onMounted,ref } from 'vue'
import { Download,RefreshCw } from '@lucide/vue'
import AdminSelect from './AdminSelect.vue'
import AdminPagination from './AdminPagination.vue'
import {usePagedRows} from '../composables/usePagedRows'
import {api,state,dateString,money} from '../state'
const from=ref(dateString(-6)),to=ref(dateString()),windowId=ref(''),data=ref(null),busy=ref(false),downloading=ref(false),error=ref(''),loaded=ref('')
const windows=computed(()=>[{value:'',label:'全部窗口'},...state.windows.map(item=>({value:item.id,label:item.canteenName+' · '+item.name}))])
const rows=computed(()=>data.value?.daily||[]),summary=computed(()=>data.value?.summary||{})
const {viewport,page,pageSize,total,visibleRows}=usePagedRows(rows,{rowHeight:48,headerHeight:44})
const parameters=()=>new URLSearchParams({fromDate:from.value,toDate:to.value,...(windowId.value!==''?{windowId:String(windowId.value)}:{})}).toString()
const changed=computed(()=>loaded.value!==parameters())
/** 成功后才替换报表；查询条件变动时阻止把旧汇总和新范围导出混淆。 */
async function load(){if(busy.value)return;busy.value=true;error.value='';const query=parameters();try{const result=await api('/staff/reports?'+query);data.value=result;loaded.value=query;page.value=1}catch(cause){error.value=cause.message}finally{busy.value=false}}
/** 使用同一已确认筛选条件下载真正的 XLSX，失败保留当前报表并显示错误。 */
async function download(){if(downloading.value||changed.value)return;downloading.value=true;error.value='';try{const response=await fetch('/campus/staff/reports/export?'+loaded.value,{headers:{Authorization:'Bearer '+state.token}});if(!response.ok||!response.headers.get('content-type')?.includes('spreadsheetml')){let payload={};try{payload=await response.json()}catch{}throw new Error(payload.msg||'导出未完成，请重新登录或重试')}const blob=await response.blob(),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`饭点经营报表-${data.value.fromDate}-${data.value.toDate}.xlsx`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(cause){error.value=cause.message}finally{downloading.value=false}}
defineExpose({load})
onMounted(load)
</script>
<template><section class="br-panel"><form class="br-filters" @submit.prevent="load"><label>取餐开始日期<input v-model="from" type="date" aria-label="报表开始日期" required /></label><label>取餐结束日期<input v-model="to" type="date" aria-label="报表结束日期" required /></label><AdminSelect v-if="state.account.role==='ADMIN'" v-model="windowId" :options="windows" label="报表窗口" /><button class="am-secondary" :disabled="busy"><RefreshCw :size="15" />{{busy?'查询中…':'查询'}}</button><button type="button" class="am-primary" :disabled="!data||changed||busy||downloading" @click="download"><Download :size="16" />{{downloading?'正在导出…':'导出 Excel'}}</button></form><p class="br-note">按取餐日期统计，收入仅计已核销订单，退款单独列示。单次最多查询 366 天。{{changed&&data?'条件已变更，请查询后再导出。':''}}</p><p v-if="error" role="alert" class="br-error">{{error}}</p><div v-if="data" class="br-metrics"><div><span>预约订单</span><strong>{{summary.orders}}<small>笔</small></strong></div><div><span>已核销收入</span><strong>¥{{money(summary.revenue)}}</strong></div><div><span>已核销订单</span><strong>{{summary.completed}}<small>笔</small></strong></div><div><span>已退回金额</span><strong>¥{{money(summary.refund)}}</strong></div></div><div ref="viewport" class="br-viewport"><table class="data-table"><thead><tr><th>取餐日期</th><th>预约数</th><th>已核销</th><th>核销收入</th><th>取消数</th><th>退款金额</th></tr></thead><tbody><tr v-for="row in visibleRows" :key="row.day"><td>{{row.day}}</td><td>{{row.orders}}</td><td>{{row.completed}}</td><td>¥{{money(row.revenue)}}</td><td>{{row.cancelled}}</td><td>¥{{money(row.refund)}}</td></tr></tbody></table></div><AdminPagination v-model="page" :total="total" :page-size="pageSize" label="经营日报分页" unit="天" /></section></template>
<style scoped>
.br-panel{display:flex;flex:1;flex-direction:column;min-height:0;padding:18px 20px;gap:14px}.br-filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.br-filters label{font-size:12px;color:var(--ed-muted)}.br-filters input{display:block;background:var(--ed-head);color:var(--ed-ink);border:1px solid var(--ed-rule);border-radius:10px;padding:9px;margin-top:6px;font-size:14px;height:42px}.br-filters .admin-select{width:170px}.br-note{font-size:12px;color:var(--ed-muted);line-height:1.6}.br-error{font-size:13px;color:#ad4938}.br-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.br-metrics>div{background:var(--ed-head);padding:16px;border-radius:14px;min-width:0}.br-metrics span{font-size:12px;color:var(--ed-muted)}.br-metrics strong{display:block;font-size:25px;font-weight:500;margin-top:10px;overflow-wrap:anywhere}.br-metrics small{font-size:12px;margin-left:6px;color:var(--ed-muted)}.br-viewport{flex:1;min-height:0;overflow:auto}.br-viewport table{min-width:620px;table-layout:fixed}.br-viewport th{height:44px;font-size:12px}.premium-workbench .ops-panel .br-viewport .data-table td{height:48px;padding:10px 12px;font-size:14px;line-height:20px}.br-panel>.admin-pagination{border-top:1px solid var(--ed-rule);flex:none}@media(max-width:899px){.br-viewport{min-height:220px}.br-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.br-panel{padding:14px}.br-filters{gap:8px}.br-filters label{flex:1;min-width:130px}.br-filters input{width:100%}}
</style>
